  "heroglyph.flow.dogCharacter.slide.guardian.desc": "Kapıyı öbür dünyanın kapısıymış gibi bekler. Önce havlar, soru sormaz — hiç.",
  "heroglyph.flow.dogCharacter.slide.player.desc": "Bir top atışı daha için ruhunu satar. En büyük mutluluğu: en sevdiği oyuncak.",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "Kapatma düğmesi yok. Pil gerekmez. En sık sorulan soru: bu köpek ne kullanıyor?",
  "heroglyph.flow.dogCharacter.slide.maverick.desc": "Kendi dünyası, kendi kuralları olan modern bir korsan. Seçici işitme onun ilk yasası.",
