  "about.origin.title": "Köken<br />Hikayesi",
  "about.origin.sub": "Kaydır ve oku",
  "about.origin.skip": "veya atla",
  "about.crawl.intro": "On yıl önce, Avrupa'nın kalbindeki bir barınakta….",
  "about.crawl.episode": "Bölüm I",
  "about.crawl.faith": "Yeni Bir İnanç",
  "about.crawl.p1": "2016'da, sekiz siyah yavru aynı bir kutuda atılmış halde barınağa geldi. Yedisi yuva buldu. En büyüğünü kimse istemedi — tam bir yıl bekledi. Adı Hekthor'du.",
  "about.crawl.p2": "Bir gün bir çift, evlat edinmek istedikleri küçük beyaz dişi Sindy'yi görmek için barınağa geldi. Tamamen tesadüfen, Hekthor o sırada Sindy'nin bölmesindeydi — kendi bölmesi temizleniyordu. Sadece eşine eşlik etmek için gelen ve hiç köpek istemediğini söyleyen adam, hayatında ilk kez gördüğü siyah köpeğe âşık oldu.",
  "about.crawl.p3": "Bir hafta sonra ikisi birlikteydi ve güzel bir hikaye başladı. Adamın tüm hayatı değişti; zamanla bir şeyi anladı: köpeği olan ve bir köpeğin sevgisinin nasıl hissettirdiğini bilen biri ancak gerçekten ihtiyaç içindeki köpeklere yardım edebilir.",
  "about.crawl.p4": "Ve böylece Heroglyph doğdu — dünyanın her yerindeki köpek sevdalılarını insanlığın gördüğü en büyük topluluğa birleştirmeye yönelik bir sembol. Kendimiz için, köpeklerimiz için ve gelecek nesiller için ayağa kalkacak — bir köpeğin sadece bir hayvan değil, bizi daha iyi insanlar yapan bir varlık olduğunu kabul etmekten korkmayan insanlar için — bir topluluk.",
  "about.crawl.p5": "Şu anda ilk kilometre taşına yolculuk başlıyor — 1.000.000 Heroglyph oluşturmak. Ve siz de bunun bir parçası olabilirsiniz. Çünkü dünyayı değiştirebileceklerine yetecek kadar deli olanlar, bunu gerçekten yapanlardır.",
  "about.crawl.p6": "Köpeğe inanıyoruz.",
  "about.timeline.heading": "DOGYPT'in Hikayesi",
  "about.milestone.1.year": "2017",
  "about.milestone.1.tag": "Barınak",
  "about.milestone.1.title": "Barınaktaki Hazine",
  "about.milestone.1.body": "Kimsenin istemediği siyah bir köpek barınak çitinin arkasında bekliyordu. Adı Hekthor oldu. Onu evlat edinmek kurtarma değildi — her şeyin başlangıcıydı.",
  "about.milestone.2.year": "2018",
  "about.milestone.2.tag": "Bağ",
  "about.milestone.2.title": "Ebedi Bir Bağ",
  "about.milestone.2.body": "Tek bir kelime etmeden hayatımın en zor döneminden geçirmeme yardım etti. Her köpek sevdalısı bunu bilir — tam düşerken sizi tam o an taşırlar.",
  "about.milestone.3.year": "2019",
  "about.milestone.3.tag": "Yolculuk",
  "about.milestone.3.title": "Kitaba Dönüşen Yürüyüş",
  "about.milestone.3.body": "Birlikte Slovakya'yı baştan başa yürüdük — 42 gün, 800 kilometre, sessiz bir söz. O yol bir kitap oldu: „Cesta s Hrdinom\" — Kahramanla Yol.",
  "about.milestone.4.year": "2022",
  "about.milestone.4.tag": "İsim",
  "about.milestone.4.title": "Köpek Sevdalıları Ulusu",
  "about.milestone.4.body": "Piramitler, mistisizm, Mısır'ın ebedi ihtişamı — insanlık çağlar boyunca bunlara hayran kaldı. Bunu bir köpeğin sonsuz sevgisiyle birleştirdiğinizde DOGYPT ortaya çıkar. Fikri 2022 Dubai Expo'da firavun kıyafetiyle mühürledim.",
  "about.milestone.5.year": "Şimdi",
  "about.milestone.5.tag": "Dogypt",
  "about.milestone.5.title": "Yolculuk Sizinle Başlıyor",
  "about.milestone.5.body": "DOGYPT, hayatı bir köpek tarafından değiştirilen herkesin hareketidir. Dünyanın en eski, en dürüst bağı üzerine kurulu. Hekthor kurucu #1. Sıra sizde.",
  "about.outro.quoteLead": "Hiçbir Zaman",
  "about.outro.quoteTail": "\"Sadece Bir Köpek\" Değildi.",
  "about.outro.body": "O hissi zaten biliyorsunuz — bir köpeğin sahip olunan bir şey değil, <strong>sevilen biri</strong> olduğunu. Şimdi o sevgiyi organize, bağlantılı, <strong>değişim yaratmaya yetecek güçte</strong> hayal edin. Ve DOGYPT bunun için var.",
  "about.outro.name1": "Matej",
  "about.outro.and": "ve",
  "about.outro.name2": "Hekthor",
  "about.outro.cta": "Dogiptli Ol",
  "about.reel.prev": "Önceki fotoğraf",
  "about.reel.next": "Sonraki fotoğraf",
  "religion.hook.number": "1.2",
