  "religion.hook.bow": "ineğe tapıyor",
  "religion.hook.doglovers": "KÖPEK SEVDALILARı?",
  "religion.hook.worship": "GELİN KÖPEKLERİMİZE TAPALIM.",
  "religion.cta": "Dogiptli Ol",
  "religion.aria.question": "Soru",
  "religion.aria.preamble": "Önsöz",
  "religion.aria.sacredIndex": "Kutsal Dizin",
  "religion.aria.scrollDown": "Aşağı kaydır",
  "religion.preamble.headlineGrad": "Köpeğe",
  "religion.preamble.headlineLine": "Güveniyoruz",
  "religion.preamble.text": "Biz, köpek sevdalıları ulusu olarak — yeryüzündeki her köpeğin <strong>sonsuz sadakatini</strong>, <strong>gerçek sevgisini</strong> ve <strong>saf ruhunu</strong> bilerek — köpeklerin insan toplumundaki konumunu yükseltmek, onlar için bir <strong>topluluk</strong> kurmak, yaşamlarını <strong>iyileştirmek</strong> ve ihtiyaç içindeki her köpeğin kaderini <strong>yeniden yazmak</strong> amacıyla kendimize bu anayasayı veriyoruz.",
  "religion.preamble.oath": "Sürü Yemini",
