  "whatNext.motto": "Köpeğe güveniyoruz.",
  "whatNext.s1.title": "İlk Adım",
  "whatNext.s1.hook": "İnsan için küçük bir adım — köpek soyu için devasa bir sıçrayış.",
  "whatNext.s1.body": "Heroglyph'in seni dünya genelinde köpekleri onurlandıran bir hareketin parçası ilan etti. <b>İlk adım atıldı.</b>",
  "whatNext.s2.title": "Artık Bir Dogiptlisin",
  "whatNext.s2.hook": "Sen bir köpek sevdalısı değilsin — tasmalı bir inançlısın.",
  "whatNext.s2.body": "WALL'a yazıldın, sonsuza dek. Her birimiz biraz verir — ve <b>birlikte, köpeklere yeterince veririz.</b>",
  "whatNext.s3.title": "Değişimin Parçası Ol",
  "whatNext.s3.hook": "Tek bir pati bir iz bırakır. Bir milyon pati bir yol açar.",
  "whatNext.s3.body": "Bir milyon heroglyphs'e ulaşmamıza yardım et — arkadaşlarını davet et. <b>Daha fazla heroglyphs = her köpek için daha fazla iyilik.</b>",
  "whatNext.s4.title": "İletişimde Kal",
  "whatNext.s4.hook": "Kapı açık. Pack bekliyor.",
  "whatNext.s4.body": "E-postanı kontrol et ve profiline giriş yap — iletişimimizi orada sürdüreceğiz. <b>Köpeklerimiz için ömür boyu bir uygulama yolda.</b>",
