  "entry.criteria.community.body": "Biz amacı olan köpek sevdalılarıyız. Tek başına her birimiz az şey değiştirebilir — birlikte, gücümüzün sınırı yok.",
  "entry.criteria.symbol.title": "Sembol",
  "entry.criteria.symbol.body": "Her inancın bir işareti vardır. Bizimki Heroglyph: her köpek için eşsiz kutsal bir im, her dilde, her yerde anlaşılır.",
  "entry.criteria.ritual.title": "Ritüel",
  "entry.criteria.ritual.body": "Yürüyüş. Bedeni ve zihni formda tutan günlük terapi — ve ruhu da. Kimse söylemeden zaten sürdürdüğümüz en eski ritüel.",
  "entry.criteria.vision.title": "Vizyon",
  "entry.criteria.vision.body": "İnsan ve köpek arasındaki bağı yüceltmek — ve her köpeğin hakkı olan saygı ve daha iyi yaşam için savaşmak.",
  "entry.criteria.offerings.title": "Adak",
  "entry.criteria.offerings.note": "(sembolik bir katkı)",
  "entry.criteria.offerings.pill": "€11 · tek seferlik",
  "entry.criteria.offerings.tag": "%100 şeffaflık",
  "entry.criteria.offerings.body": "€11, bir kez. Sembolik bir adak — her gelir ve her gider herkese açık bir defterde. Bizi ayakta tutan enerji.",
  "entry.criteria.legitimacy.title": "Meşruiyet",
  "entry.criteria.legitimacy.pill": "{count} üye kaldı",
  "entry.criteria.legitimacy.body": "Bin kurucu, ve yasanın tanımak zorunda olduğu bir ulus olarak kaydolacak kadar güçlüyüz. Son işaret — ona yalnızca sen ulaşabilirsin.",
  "entry.criteria.doneLabel": "tamam",
