  "heroglyph.flow.more.ainubis.t": "AINUBIS",
  "heroglyph.flow.more.cause.d": "DOGYPT köpek severlerin hayatını kolaylaştırır; ama aynı zamanda iyi insanları bir araya getirir ve muhtaç köpeklere şeffaf biçimde yardım eder. DOGYPT’in kurucusu HEKTHOR bile bir barınaktan geliyor.",
