  "heroglyph.flow.more.dogid.t": "DOG ID",
  "heroglyph.flow.more.dogtrip.d": "Dünyanın dört bir yanından köpek dostu maceralar tek bir yerde. En sevdiğin geziyi ekle, sürüyle paylaş. Başkalarından ilham al; puan, rozet ve seviye topla.",
