  "heroglyph.flow.more.glyph.t": "HEROGLYPH",
  "heroglyph.flow.more.money.d": "Her €11’in €5’i geliştirmeye, €3’ü topluluğa, €2’si köpek kurtarmaya, €1’i Hekthor’un kabına gider. Her harcama belgelenecek ve herkese açık olacak.",
