  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. Sürünün İçinde: Diğer Üyeler Ne Görür",
  "privacy.s12.body": "3. bölüm herkese açık GodsGrid'i açıklar. Sürünün içinde — yalnızca üyelere açık alanda — diğer giriş yapmış Üyeler daha fazlasını görür: adını, Dogiptli numaranı, köpeğinin adını ve fotoğrafını, köpeğin için doldurduğun özellikleri, kaydettiğin veya duyurduğun gezileri, puanlarını ve yorumlarını ve profilinde yazdığın her şeyi. E-posta adresini, posta adresini, ödeme bilgilerini veya başka biriyle olan mesajlarını görmezler. Bir geziyi açık olarak duyurduğunda, rota, tarih ve köpeğin katılmak isteyen her Üyeye görünür hale gelir — duyurmak tam olarak bunu ifade eder. Özel tuttuğun bir gezi sadece sana ve zaten gidenlere görünür. İkisinden hangisini seçeceğine sen karar verirsin ve bunu istediğin zaman değiştirebilirsin.",
  "privacy.s13.title": "13. Mesajlar ve Şikayetler",
  "privacy.s13.body": "Üyeler arasındaki özel mesajlar, oturumlar arasında konuşmaların kaybolmaması için veritabanımızda (Supabase) saklanır. Hukuki dayanak: GDPR md. 6(1)(b) — bunlar ödediğin üyeliğin bir parçasıdır. Bunları rutin olarak okumayız ve asla reklam veya profilleme için kullanmayız. Bir konuşmayı yalnızca şikayet edildiğinde, belirli bir kötüye kullanımı veya güvenlik olayını araştırdığımızda ya da kanun gerektirdiğinde açarız. Bir şikayet, seçtiğin nedeni, isteğe bağlı notunu ve şikayet ettiğin şeye bir referansı saklar — ayrı bir kopyasını değil. Engelleme, bir üye kimliği çifti olarak saklanır. Hesabını silersen mesajların onunla birlikte gider; diğer kişinin akışındaki kopya, o konuşma da ona ait olduğu için kaldırılmış bir üyeden geliyormuş gibi gösterilerek kalır.",
  "terms.s12.title": "12. Paylaştığın İçerik",
  "terms.s12.body": "HEROGLYPH'inin yanında sürü içinde içerik paylaşabilirsin: gezi fotoğrafları, rotalar ve konumlar, gezi açıklamaları, puanlar, yorumlar ve sorular ve profilinde yazdığın her şey. Bir geziyi yürünmüş olarak işaretlediğinde, diğer Üyeler adını ve onu seninle birlikte yürüyen köpekleri görür. Paylaştığın her şeyin sahipliği sende kalır. Bunu paylaşarak DOGYPT s.r.o.'ya, Hizmeti işletmek ve tanıtmak amacıyla bu içeriği saklamak, göstermek ve uyarlamak için dünya çapında, telifsiz, münhasır olmayan bir lisans verirsin — örneğin gezi fotoğrafını haritada, bir gezi listesinde veya bir paylaşım kartında göstermek gibi. Lisans, içerik Hizmette olduğu sürece geçerlidir; içeriği veya hesabını kaldırdığında sona erer, yedekler hariç — onlar kendi normal döngülerinde sona erer. İçeriğini satmayız ve onu başka kimseye kendi kullanımı için lisanslamayız. Yalnızca paylaşma hakkına sahip olduğun şeyleri paylaş — bu, başkasının çektiği fotoğrafları ve onlarda tanınabilir olan kişileri de kapsar.",
  "terms.s13.title": "13. Üyeler Arası Mesajlar",
  "terms.s13.body": "Üyeler birbirine doğrudan yazabilir. Mesajlar katılımcılar arasında özeldir — bunları rutin olarak okumayız ve asla reklam için kullanmayız. Geri döndüğünde konuşma hâlâ orada olsun diye sunucularımızda saklanır ve bir konuşmayı üç durumda okuyabiliriz: biri şikayet ettiğinde, belirli bir kötüye kullanımı veya güvenlik olayını araştırdığımızda ya da kanun gerektirdiğinde. Başka bir Üyeyi istediğin zaman engelleyebilirsin; engelleme anında devreye girer ve iki yönlü çalışır. Mesajlara, saklanmasını istemeyeceğin herhangi bir çevrim içi konuşmaya davrandığın gibi davran — ödeme bilgileri, şifreler veya saklanmasını istemediğin belgeler gönderme.",
  "terms.s14.title": "14. Şikayet ve Moderasyon",
  "terms.s14.body": "Profiller, geziler ve konuşmalar şikayet edilebilir. Bir şikayet bize ulaşır ve bunu bir insan okur — bugün bu kurucu Matej Stacho'dur. Her şikayete 7 gün içinde bakmayı hedefliyoruz. Bulduğumuza bağlı olarak hiçbir şey yapmayabiliriz, içeriği kaldırabiliriz, Üyeyi uyarabiliriz, ne paylaşabileceğini sınırlayabiliriz veya hesabını kapatabiliriz. İçeriğine bir işlem yaparsak nedenini e-postayla sana bildiririz ve yanıtlayıp itiraz edebilirsin. 7. bölümü ihlal ettiğinde içeriği kendi inisiyatifimizle de kaldırabiliriz. Kasıtlı veya tekrarlanan kötüye kullanım — taciz, spam, sahte geziler, reşit olmayanları içeren içerik — hesabı başka bir uyarı yapılmadan sonlandırır.",
  "dogPage.bonesForDog": "Bu sayfadan katıl, {dog} 20 BONES kazansın.",
