  "pack.cal.life.tgtPre": "Hedef:",
  "pack.cal.life.tgtBody": "holistik bakımın ekleyebileceği beş yıla kadar fazladan ömür — zayıf kalmak, arazide hareket, dişler, uyku ve mümkün olduğunca az gereksiz kimyasal.",
  "pack.cal.life.tgtSrc": "Kaba bir tahmin, bir söz değil. Bunun sadece bir kısmı ölçüldü: sadece zayıf kalmak labradorlara 1,8 yıl ekledi (Purina Life Span Study, JAVMA 2002).",
  "pack.cal.life.intro": "Aşağıda köpeğinin tüm hayatı bloklar hâlinde. Bir blok = bir hafta, bir satır = bir yıl. Bir yandan ürkütücü, diğer yandan tam da her anın tadını çıkarmak ve işleri ertelememek için bir hatırlatma.",
  "pack.cal.life.fromBirth": "Doğumdan itibaren sayılır",
