  "pack.cal.life.recSince": "{year}'den beri",
  "pack.cal.life.tip.weight.title": "Zayıf kalmak kanıtlanmış olan tek şey",
  "pack.cal.life.tip.weight.body": "Bir köpek için yapabileceğin her şeyden, yaşam süresi için en sağlam kanıta sahip olan bir şey var: kilo almasına izin vermemek. Zayıf bir köpekle hafif kilolu bir köpek arasındaki fark yıllardır, aylar değil. Kaburgalarını bastırmadan hissedebilmelisin.",
  "pack.cal.life.tip.move.title": "Gerçek arazide hareket, evin etrafında bir tur değil",
  "pack.cal.life.tip.move.body": "Engebeli arazi eklemleri, kasları ve zihni çalışır tutar. Kaydettiğin her gezi bu ızgarada koyu bir haftaya dönüşür — ve koyu haftalar gerçekten etkileyebileceğin tek şey.",
  "pack.cal.life.tip.food.title": "Köpeğin yemek olarak tanıdığı yemek",
  "pack.cal.life.tip.food.body": "Ham malzeme ile kap arasındaki adım sayısı ne kadar azsa, yolda ters gidebilecek şey de o kadar az olur. Kuru mama bir günah değil, ama bir diyet de değil — bir kestirme yol.",
  "pack.cal.life.tip.chem.title": "Kimyasallar sadece gerçekten gerektiğinde",
  "pack.cal.life.tip.chem.body": "Yıl boyunca parazit ilaçları, konfor için anestezi ve \"ihtiyaten\" antibiyotikler birer karardır, rutin değil. Her biri için sor: bunu yapmazsam ne olur? Cevap \"hiçbir şey\" olduğunda yapma.",
  "pack.cal.life.tip.stress.title": "Dinlenme de hareket kadar önemlidir",
  "pack.cal.life.tip.stress.body": "Her zaman tetikte olan bir köpek bedenini içten yakar. Rahatsız edilmeden uyumak, öngörülebilir bir gün ve efor sonrası sessizlik tembellik değildir — bedenin kendini onardığı saatlerdir.",
  "pack.cal.life.tip.protocol.title": "Panik hâlinde veterinere koşmak yerine bir protokol",
  "pack.cal.life.tip.protocol.body": "Parazit tedavisinin, koprolojinin ve kan tahlilinin takvimde kendi pencereleri var. Kanı yılda iki kez kontrol edilen bir köpek tedavi edilmiyor — önüne geçiliyor.",
  "pack.cal.life.tip.joints.title": "Eklemler ağrımaya BAŞLAMADAN ele alınır",
  "pack.cal.life.tip.joints.body": "Köpeğin artık yaşlı kategorisinde. Eklem kürünün takvimde kasımdan itibaren bir penceresi var — topalladığı için değil, hiç topallamasın diye.",
