  "pack.nature.balance.body": "Köpeğinin yapısı ömür boyu sabittir, ama dengeden çıkabilir. Geçerli olan her şeyi işaretle — istediğin kadar ya da hiç.",
  "pack.nature.balance.none": "Listede hiçbir şey yok mu? Boş bırak ve devam et — var olan en iyi cevap bu.",
  "pack.nature.progress": "İlerleme",
  "pack.nature.special.eyebrow": "Dört tane daha — özel roller arıyoruz",
