  "pack.nature.special.cta": "Sonucu göster",
  "pack.nature.result.saved": "Köpeğinin kartına kaydedildi",
  "pack.nature.result.savedAll": "Her köpeğin kartına kaydedildi",
  "pack.nature.ans.yes": "Evet",
  "pack.nature.ans.sometimes": "Bazen",
  "pack.nature.ans.no": "Hayır",
  "pack.network.ads.body": "Ücretli reklamlar yeni köpek severler bulmak için çok verimsiz bir yoldur — ve paramızı büyük şirketlere atma yoludur. Hareketin üyelerini aktif olmaları için doğrudan ödüllendirmek çok daha iyi çalışır. Bir yakalama var: <strong style=\"font-weight:600\">bu gerçekten sadece dışarı çıkıp etrafındaki insanlara bizden bahsedersen işe yarar</strong> :)",
  "pack.network.ads.header": "Neden bu şekilde?",
