  "pack.network.capped.none": "Bundan bağlılık yok — hediyelerin zaten yaşadığın her şeyle eşleşiyor. BONES yine de geçer. <i>Para yılları ikiye katlar, onların yerini asla almaz.</i>",
  "pack.network.capped.room": "<b style=\"color:#2a1608\">{room}</b>'da sınırlı — bir hediye sadece yaşadığınla eşleşebilir (şimdiye kadar {lived} bağlılık). BONES yine de geçer; onur günleri bekler.",
