  "pack.network.inLine": "Soyağacında",
  "pack.network.info.bones.body": "BONES, DOGYPT'in dahili para birimi — gerçek bir şey için eğlenceli bir ad. Bir köpek kemiklerle öder; biz de öyle. Köpek severleri sürüye getirerek ve hareketi ileriye taşıyarak <b>kazanırsın</b>, ve DOGYPT içinde <b>harcarsın</b>: barınak bağış kampanyalarını desteklemek, ürün almak ve daha sonra diğer Dogiptlilere yarattıkları için ödeme yapmak. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "BONES nedir?",
  "pack.network.info.why.body": "Bu büyüklükte bir hareket satın alınamaz — hiçbir bütçe bir yabancıya, bir Dogiptlinin bir arkadaşa ulaştığı gibi ulaşamaz. Bu yüzden sürü ödülü ulaşımın olduğu yere koyar — sana. Biri senin bağlantın üzerinden katıldığında <b>{l1} BONES</b> alırsın; birini daha getirdiğinde <b>{l2}</b> daha alırsın. Haberi yayan her Dogiptli bir satıcı değil — bir misyoner, ve bu işi onurlandırıyoruz.",
  "pack.network.info.why.cap": "Neden senden istiyoruz",
  "pack.network.intro": "Bir hareket sadece üyeleri mesajı taşıyıp yeni insanlar getirdiğinde büyür. Bu yüzden sana doğrudan soruyoruz: <strong style=\"color:#2a1608;font-weight:600\">tanıdığın köpek severleri davet et</strong>. İşte tam olarak nasıl çalıştığı.",
