  "onepage.apps.insp": "İlham kaynağı",
  "onepage.apps.mapy": "Haritalar:",
  "onepage.apps.claude": "Yapay zekâ:",
  "onepage.apps.dogid.lede": "Köpeğinle ilgili her ayrıntı tek yerde — veterinerinin ve AINUBIS'in sana özel bakım sunmasının anahtarı.",
  "onepage.apps.dogtrip.lede": "Doğrulanmış köpek dostu rotaları keşfet, kendi rotalarını kaydet. Birlikte geçirdiğin hareketli hayat için puan ve rozet topla.",
  "onepage.apps.sniffer.lede": "Köpek dostu bir eşleştirme servisi. Dünyayı keşfetmek için bir dost, bir ekip ya da bir partner bul — tek bir sürü olarak.",
  "onepage.apps.cause.name": "TOPLULUK GÜCÜ",
  "onepage.apps.cause.lede": "DOGYPT'i köpek sevgisiyle birlikte kuruyoruz — %100 şeffaf. Her üye tüm gelir ve giderleri görür.",
  "onepage.apps.ainubis.lede": "Köpeğini iyice tanıyan, sana özel yapay zekâ mentorumuz — doğrulanmış kitaplardan, yazılardan ve kısa podcast'lerden beslenir.",
  "onepage.apps.head": "Üyelik",
  "onepage.apps.sub1": "Bir köpek dünyası kuruyoruz — her köpek sevdalısı için yardımsever, eğlenceli bir ekosistem.",
  "onepage.apps.chips.lead": "En iyilerin bir arada olduğu tek uygulama:",
  "onepage.apps.chips.more": "ve çok daha fazlası…",
  "onepage.apps.chips.tail": "…köpek sevdalılarına özel hazırlandı.",
  "onepage.apps.lang.a": "Heroglyph evrensel bir dildir.",
  "onepage.apps.lang.b": "Uygulama bunların 18 tanesini konuşuyor.",
  "onepage.apps.more": "Ayrıntı",
  "onepage.apps.tap": "dokun",
  "onepage.apps.prev": "Önceki",
  "onepage.apps.next": "Sonraki",
  "onepage.fin.photoAlt": "Matej ve Hektor",
  "onepage.fin.forMe": "(benim için)",
  "onepage.fin.p1": "Merhaba, ben Matthew. Dokuz yıl önce hayatım değişti — barınaktan gelen bir köpek yüzünden. Bir köpeğin sevgisinin gücünü hissedince, köpeklerin bu iyiliğini nasıl karşılayabileceğime dair bir vizyonum oldu — sadece benimkinin değil, dünyadaki her köpeğin.",
  "onepage.fin.p2": "O zamanlar sadece bir fikirdi — yapay zekâ sayesinde sonunda onu inşa edebiliyorum. Hava güzel olduğunda Hekthor'la gezilerdeyim, o dinlenirken ben DOGYPT için canla başla çalışıyorum. Bu misyona tutkunum — her şeyimi ona feda ediyorum, kazandığım her euroyu ona yatırıyorum. Yakınlarım hayalperest olduğumu ve fazla risk aldığımı söylüyor — ama bu fikrin uğruna savaşmaya değdiğine ve bunun sadece zaman meselesi olduğuna ikna oldum.",
  "onepage.fin.p3": "Lütfen bizi bekletme — bugün aramıza katıl, ki B planına (OnlyFans) geçmek zorunda kalmayayım.",
  "onepage.fin.aboutMore": "Hakkımda daha fazlası",
  "onepage.fin.liveHead": "Canlı durum",
  "onepage.fin.aiLine": "Bu proje <b>köpeklere</b> duyulan sevgiyle — ve <b>yapay zekâyla</b> inşa ediliyor.",
