  "onepage.hbook.0.title": "Evvel zaman içinde…",
  "onepage.hbook.0.glyph": "Hekthor'un heroglyph'i",
  "onepage.hbook.0.sub": "Hekthor · köpek #1",
  "onepage.hbook.0.cap": "Ayna",
  "onepage.hbook.1.ini": "S",
  "onepage.hbook.1.lead": "ahipsiz doğdu. Bir kutuya atıldı; orada kardeşleriyle birlikte ölümü bekledi.",
  "onepage.hbook.1.txt": "Sekiz minik can bir barınağa düştü. Yedisi yuva buldu. Yalnızca biri geride kaldı — en iri olan, en büyük mizacı olan. Bir yıl sonra, tamamen tesadüfen, hiç köpek sahibi olmayı planlamamış Matej'le karşılaştı. Bir kıvılcım çaktı ve Haziran 2017'den beri hayatta birlikte yürüyorlar.",
  "onepage.hbook.1.cap": "Kutuda sekiz",
  "onepage.hbook.2.ini": "B",
  "onepage.hbook.2.lead": "ir insanın hayatını kurtardı. O hayatın en zor mevsiminde geldi.",
  "onepage.hbook.2.txt": "En karanlık zamanlarda Matej'in çapasıydı — onu karanlık düşüncelerden, evden çıkarıp doğaya çekti. Önce yakın sokaklar, sonra ormanlar ve dağlar. Tüm Slovakya'yı (820 km) yürüdüler ve Avrupa'yı baştan başa yol gezileriyle dolaştılar. Macera ve yollardaki özgür hayat onları birbirine bağladı.",
  "onepage.hbook.2.cap": "Ofisten dünyaya",
  "onepage.hbook.3.ini": "S",
  "onepage.hbook.3.lead": "af ruhu, köpek sevenler için küresel bir hareketin vizyonunu getirdi.",
  "onepage.hbook.3.txt": "Bir köpekle yaşamak, herkesin hayatının en güzel bölümüdür. Köpek insanları başka türden insanlardır — hep aynı özel sorunları yeniden çözerler ve köpek sevgisiyle birbirlerine bağlıdırlar. Ya bu hikâye işe yarar bir şeye dönüşürse?",
  "onepage.hbook.3.cap": "Bir vizyon doğuyor",
  "onepage.hbook.4.ini": "O",
  "onepage.hbook.4.lead": "n güzel yıl geride kaldı, önünde en az on yıl daha var!",
  "onepage.hbook.4.txt": "Hekthor, Matej'e köpekler hakkında her şeyi öğrenmesi için ilham verdi — psikoloji, eğitim, spor ve her şeyden önce uzun ömür. Tüm bu bilgi DOGYPT'te herkese hizmet edecek: bir başka gösterişli sosyal ağ değil, anlamlı içeriği olan bir ağ. Ve hepsi “sıradan” bir barınak köpeği sayesinde.",
  "onepage.hbook.4.cap": "Kurucu #1",
  "onepage.hbook.5.ini": "B",
  "onepage.hbook.5.lead": "ugün Slovakya'da yaşıyor — ormanlarda, dağlarda ve göllerin kıyısında.",
  "onepage.hbook.5.txt": "Sudan getirmek onun en büyük aşkı. Formunun zirvesinde, bilge, mütevazı ve insanın dileyebileceği en iyi yoldaş. Dışarıda olmadığımız zamanlarda, sokaktan kurtardığı iki erkek kedi Gary ve Yby'ye evde göz kulak oluyor.",
  "onepage.hbook.5.cap": "Evin koruyucusu",
